+import type { DepoCatalogueReviewers, UpdateCatalogueReviewersParams } from '@/apis/modules/catalogue/module';
+import { DepoCatalogueReviewEnum } from '@/apis/modules/catalogue/module';
+import { gsModalSize } from '@/utils/commonVariable';
+import { Button, Form, Modal, Radio, message } from 'antd';
+import { useEffect, useMemo, useState } from 'react';
+import { UserSelect } from '../UserSelect';
+import { useCatalogueTree } from '@/hooks/useCatalogueTree';
+import type { IUserInfo } from '@/apis/modules/user/module';
+import { updateCatalogueReviewers } from '@/apis/modules/catalogue';
+
+export const AddReviewConfig = ({ currentReviewList }: { currentReviewList: DepoCatalogueReviewers }) => {
+  const [isOpen, setIsOpen] = useState(false);
+
+  const [loading, setLoading] = useState(false);
+
+  const [userList, setUserList] = useState<IUserInfo[]>([]);
+
+  const { computedSelectItem, reloadCatalogueItemReviewers } = useCatalogueTree.useShallowSelector((s) => ({
+    computedSelectItem: s.computedSelectItem,
+    reloadCatalogueItemReviewers: s.getCatalogueItemReviewers,
+  }));
+
+  const [form] = Form.useForm<{ reviewers: number[]; type: DepoCatalogueReviewEnum }>();
+
+  const selectedList = useMemo(() => currentReviewList.map(i => i.reviewers || []).reduce((p, c) => p.concat(c), []), [currentReviewList])
+
+  useEffect(() => {
+    return () => form.resetFields();
+  }, [form, isOpen]);
+
+  const onSubmit = async () => {
+    if (loading) return;
+    try {
+      setLoading(true);
+      const formValue = await form.validateFields();
+      if (!computedSelectItem) {
+        message.error('意料之外的错误，请刷新重试');
+        return;
+      }
+      const params: UpdateCatalogueReviewersParams = {
+        dirId: computedSelectItem.id,
+        updateCatalogueReviewLevels: [
+          {
+            level: currentReviewList.length + 1,
+            type: formValue.type,
+            reviewers: userList
+              .filter((i) => formValue.reviewers.includes(i.id))
+              .map((i) => ({ id: i.id, username: i.username, nickname: i.nickname })),
+          },
+        ],
+      };
+      const response = await updateCatalogueReviewers(params);
+      if (response.success) {
+        await reloadCatalogueItemReviewers();
+        setIsOpen(false);
+      }
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <>
+      <Button onClick={() => setIsOpen(true)}>新增审查层级</Button>
+      <Modal
+        title="新增审查层级"
+        visible={isOpen}
+        okText="提交更改"
+        width={gsModalSize}
+        onOk={onSubmit}
+        confirmLoading={loading}
+        onCancel={() => setIsOpen(false)}
+      >
+        <Form form={form} labelCol={{ span: 4 }} wrapperCol={{ span: 20 }} initialValues={{ type: DepoCatalogueReviewEnum.OR }}>
+          <Form.Item label="直接审查人" name="reviewers" rules={[{ required: true, message: '请选择审查人' }]}>
+            <UserSelect
+              mode="multiple"
+              onLoad={(list) => setUserList(list)}
+              disableItems={selectedList}
+              filterOption={(input, option) => !!option?.label?.toString().toLowerCase().includes(input?.toLowerCase())}
+            />
+          </Form.Item>
+          <Form.Item label="审查条件" name="type" rules={[{ required: true, message: '请选择审查条件' }]}>
+            <Radio.Group size="middle" style={{ width: '100%' }}>
+              <Radio.Button value={DepoCatalogueReviewEnum.AND}>会签</Radio.Button>
+              <Radio.Button value={DepoCatalogueReviewEnum.OR}>或签</Radio.Button>
+            </Radio.Group>
+          </Form.Item>
+        </Form>
+      </Modal>
+    </>
+  );
+};

