export type CataLogTreeItem = {
  id: number;
  depoId: number;
  key: string;
  level: number;
  title: string;
  value: string;
  isLeaf: boolean;
  parentId: number;
  inherited: boolean;
  createTime: string;
  updateTime: string;
  reviewers: string;
  // TODO
  state: number;
  children: null | CataLogTreeItem[];
};

export type ApplyCataLogItem = {
  applyId: number;
  catalogId: number;
  createTime: string;
  updateTime: string;
  // TODO
  deleted: number;

  id: number;
  remark: string | null;
  // TODO
  reviewState: number;

  reviewers: string;
  version: number;
}

import request from '@/apis/fetcher';
import type { BasicResponse } from '@/apis/fetcher/type';
import type { ApplyCataLogItem, CataLogTreeItem } from './module';

export const getCataLogTree = (repoId: number) => {
  return request<BasicResponse<CataLogTreeItem[]>>(`/api/catalogue/getCatalogTree/${repoId}`, {
    method: 'GET',
    description: '根据仓库ID获取目录树结构',
  });
};

export const getApplyCataLogById = (applyId: number) => {
  return request<BasicResponse<ApplyCataLogItem[]>>(`/api/applyCatalog/getCatalogById/${applyId}`, {
    method: 'GET',
    description: '根据申请ID获取目录结构',
  });
};

export const getMrApplyCataLogById = (applyId: number) => {
  return request<BasicResponse<ApplyCataLogItem[]>>(`/api/mrApplyCatalog/getCatalogById/${applyId}`, {
    method: 'GET',
    description: '根据ID获取MR目录结构',
  });
};
